            tagName: 'param',
        }) as string;
        if (!preferredTagName) {
            return;
        }

        const functionParameterNames = utils.getFunctionParameterNames(
            useDefaultObjectProperties,
            interfaceExemptsParamsCheck,
        );
        if (!functionParameterNames.length) {
            return;
