                        postDelimiter: ' ',
                        postName: '',
                        postTag: ' ',
                        postType: type ? ' ' : '',
                        start: jsdoc.source[sourceIndex]!.tokens.start,
                        tag: `@${preferredTagName}`,
                        type: type ?? '',
